Item.method_code:
const { isDone, itemNode, itemTypeName } = options;

const isNew = ArasModules.item.isNew(itemTypeName, itemNode.id);
const changedItems = ArasModules.item.getItemWithDependency(
	itemTypeName,
	itemNode.id
);
if (isNew || aras.getItemProperty(itemNode, 'classification') !== 'Responsive' || changedItems.length === 0) {
	return commands.globalCommand.execute();
}

const worldIdentity = 'A73B655731924CD0B027E4F4D5FCC0A9';
const formItem = changedItems.pop();
const cuiControlItem = changedItems.pop();
const itemsForSave = [];
const { store } = aras.getMainWindow();

if (cuiControlItem) {
	const { layout, order, fields, rules, ...restChanges } = cuiControlItem;
	const cuiControlRelationships = [];
	const fieldEntries = Object.entries(fields || {});
	const fieldToRelshipMap = restChanges.Relationships?.Item?.reduce((acc, item) => {
		acc[item.related_id] = item;
		return acc;
	}, {});
	const { defaultLanguageCode } = store.getState().system;
	const getMLProps = (propName, _values) => {
		if (_values === undefined) {
			return;
		}

		if (!_values) {
			return { [propName] : null };
		}

		const values = { ..._values };
		const defaultLangValue = values[defaultLanguageCode];
		delete values[defaultLanguageCode];

		const mlPropName = `i18n:${propName}`;
		const translations = Object.entries(values).map(([lang, value]) => {
			return {
				'@attrs': {
					'xmlns:i18n': 'http://www.aras.com/I18N',
					'xml:lang': lang
				},
				'@value': value
			};
		});

		return {
			[mlPropName]: translations,
			[propName]: defaultLangValue
		};
	};

	const getAppearanceProps = (propName, value) => {
		if (value === undefined) {
			return;
		}

		return {
			[propName]: value ? '1' : '0'
		}
	};

	fieldEntries.forEach(([key, value]) => {
		const {
			'@action': action = 'edit',
			type,
			show_label: showLabel,
			show_help: showHelp,
			help_tooltip: helpTooltip,
			aria_label: ariaLabel,
			description,
			label,
			readonly,
			required,
			...rest
		} = value;
		const fieldAttributes = {
			'@attrs': {
				id: key,
				type: 'cui_FormField',
				action,
				doGetItem: '0'
			}
		};
		const fieldItem = {
			Item: {
				...fieldAttributes,
				...Boolean(type) && { field_type: type },
				...getMLProps('label', label),
				...getMLProps('aria_label', ariaLabel),
				...getMLProps('help_tooltip', helpTooltip),
				...getMLProps('description', description),
				...getAppearanceProps('show_label', showLabel),
				...getAppearanceProps('show_help', showHelp),
				...getAppearanceProps('readonly', readonly),
				...getAppearanceProps('required', required),
				...rest
			}
		};

		if (action === 'add') {
			const controlField = {
				'@attrs': {
					type: 'cui_ControlFormField',
					id: aras.generateNewGUID(),
					action,
					doGetItem: '0'
				},
				source_id: restChanges['@attrs'].id,
				related_id: fieldItem,
				action: 'Add',
				role: worldIdentity
			};
			cuiControlRelationships.push(controlField);
		} else if (action === 'delete') {
			const controlField = {
				...fieldToRelshipMap[key],
				related_id: { Item: { ...fieldAttributes } }
			};
			cuiControlRelationships.push(controlField);
		} else {
			itemsForSave.push(fieldItem);
		}
	});

	const ruleEntries = Object.entries(rules || {});
	const sourceId = restChanges['@attrs'].id;
	ruleEntries.forEach(([id, rule]) => {
		const { '@action': action } = rule;
		const controlRuleAttributes = {
			'@attrs': {
				id,
				action: action || 'edit',
				type: 'cui_ControlRule',
				doGetItem: '0'
			}
		};

		if (action === 'delete') {
			cuiControlRelationships.push(controlRuleAttributes);
		} else {
			cuiControlRelationships.push({
				...controlRuleAttributes,
				source_id: sourceId,
				...(rule.related_id !== undefined) && { related_id: rule.related_id },
				...(rule.sort_order !== undefined) && { sort_order: rule.sort_order },
			});
		}
	});

	const [xPropertiesLayoutName, xPropertiesLayoutData] =
		Object.entries(layout || {}).find(
			([, value]) => value.name === 'xProperties'
		) ?? [];
	const layoutDataForSave = xPropertiesLayoutName
		? {
				...layout,
				[xPropertiesLayoutName]: {
					...xPropertiesLayoutData,
					children: []
				}
			}
		: layout;

	itemsForSave.push({
		Item: {
			'@attrs': {
				...restChanges['@attrs'],
				action: 'edit',
				doGetItem: '0'
			},
			...(layoutDataForSave && order && { additional_data: JSON.stringify({ layout: layoutDataForSave, order }) }),
			...(Boolean(cuiControlRelationships.length) && {
				Relationships: { Item: cuiControlRelationships }
			})
		}
	});
}

changedItems.forEach(ruleItem => {
	itemsForSave.unshift({
		Item: {
			...ruleItem,
			'@attrs': {
				...ruleItem['@attrs'],
				doGetItem: '0'
			}
		}
	});
});

const isClaimed = ArasModules.item.isEditedAndClaimed(itemTypeName, itemNode.id);
const unlock = isDone && !isClaimed ? '1' : '0';

itemsForSave.push({
	Item: {
		...formItem,
		'@attrs': {
			...formItem['@attrs'],
			unlock
		}
	}
});

ArasModules.bunchSoap.collect();

const savedPromises = itemsForSave.map((element, index) => {
	const itemXml = ArasModules.jsonToXml(element);
	const itemNode = ArasModules.xml.parseString(itemXml);
	const notifySuccess = index === itemsForSave.length - 1;

	return aras.saveItemAsync(itemNode.documentElement, notifySuccess);
});

await ArasModules.bunchSoap.complete();
const results = await Promise.all(savedPromises);
const savedItem = results.pop();
const { boundActionCreators } = store;

if (savedItem && isDone) {
	savedItem.removeAttribute('isEditState');

	boundActionCreators.deleteItemLocalChangesRecord(
		itemTypeName,
		savedItem.id
	);

	const cuiControlId = cuiControlItem?.['@attrs'].id;

	if(cuiControlId) {
		boundActionCreators.deleteItemLocalChangesRecord(
			'cui_Control',
			cuiControlId,
		);
	}
} else if (savedItem) {
	changedItems.forEach(({ '@attrs': { type, id } }) => {
		boundActionCreators.deleteItemLocalChangesRecord(type, id);
	});
}

return savedItem;
